import os, json, glob
import numpy as np

def _load_json(p):
    with open(p, "r") as f:
        return json.load(f)

def _g_from(obj):
    # Accept common keys or arrays
    for k in ("gamma", "gamma_t", "gamma_mean", "g"):
        if k in obj:
            return np.array(obj[k], dtype=np.float32)
    # Some exports store under params-like dict
    if "stats" in obj and "gamma" in obj["stats"]:
        return np.array(obj["stats"]["gamma"], dtype=np.float32)
    return None

def _pc_from(obj):
    # Dict of {cond: {"step_mae": [...]}}
    out = {}
    for k, v in obj.items():
        if isinstance(v, dict) and "step_mae" in v:
            out[k] = np.array(v["step_mae"], dtype=np.float32)
    return out

def _monotonicity_violation(x):
    d = np.diff(x)
    return float(np.sum(np.clip(-d, 0, None)))

def _slope_energy(x):
    d = np.diff(x)
    return float(np.mean(d**2))

def _align_conditions(dicts):
    keys = set()
    for d in dicts:
        keys |= set(d.keys())
    agg = {}
    for k in sorted(keys):
        vals = [d[k] for d in dicts if k in d]
        if vals:
            agg[k] = np.mean(np.stack(vals, 0), 0)
    return agg

def test():
    gamma_dir = "storage/ariadne/analyses/fourier_learn_gamma_export_v2"
    pc_dir = "storage/ariadne/analyses/fourier_learn_gamma_per_condition"
    out_path = "storage/ariadne/analyses/fourier_learn_gamma_consolidated.json"

    g_files = sorted(glob.glob(os.path.join(gamma_dir, "*.json")))
    pc_files = sorted(glob.glob(os.path.join(pc_dir, "*.json")))

    gammas = []
    for p in g_files:
        try:
            g = _g_from(_load_json(p))
            if g is not None and g.ndim == 1:
                gammas.append(g)
        except Exception:
            pass

    pcs = []
    for p in pc_files:
        try:
            d = _pc_from(_load_json(p))
            if d:
                pcs.append(d)
        except Exception:
            pass

    result = {"ok": True, "n_gamma_files": len(g_files), "n_gamma_used": len(gammas),
              "n_pc_files": len(pc_files), "n_pc_used": len(pcs)}

    if gammas:
        g_mat = np.stack(gammas, 0)
        g_mean = g_mat.mean(0)
        g_std = g_mat.std(0)
        result["gamma_mean"] = g_mean.tolist()
        result["gamma_std"] = g_std.tolist()
        result["stats"] = {
            "monotonicity_violation": _monotonicity_violation(g_mean),
            "slope_energy": _slope_energy(g_mean),
            "tail_mean_last4": float(np.mean(g_mean[-4:])),
            "peak": {"value": float(g_mean.max()), "t_index": int(np.argmax(g_mean))}
        }

    if pcs:
        cond_agg = _align_conditions(pcs)
        result["per_condition_keys"] = list(cond_agg.keys())
        # Difficulty per step = mean across conditions
        if cond_agg:
            step_mat = np.stack([v for v in cond_agg.values()], 0)
            step_diff = step_mat.mean(0)
            if "gamma_mean" in result:
                a = np.array(result["gamma_mean"]) - np.mean(result["gamma_mean"])
                b = step_diff - step_diff.mean()
                denom = float(np.linalg.norm(a) * np.linalg.norm(b) + 1e-12)
                result["corr_gamma_vs_step_difficulty"] = float(np.dot(a, b) / denom) if denom > 0 else None

    os.makedirs(os.path.dirname(out_path), exist_ok=True)
    with open(out_path, "w") as f:
        json.dump(result, f, indent=2)
    print("Consolidation complete:", out_path)
    print("Files used:", result["n_gamma_used"], "gamma,", result["n_pc_used"], "per-condition")
    return result
